import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 목록 크기 기본값과 최대값
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const TARGETS = ['제목', '내용', '첨부파일 제목', '첨부파일 내용'];

// 가정: 결재문서는 기안자 본인 것만, 첨부파일은 업로드한 본인 것만 권한 범위로 본다.
// 게시물은 공개범위(ALL/DEPARTMENT/INDIVIDUAL)로 제한한다.
// 첨부파일 내용은 schema.sql에 컬럼이 없어 검색하지 못한다.
const RESULT_SQL = `
  SELECT 'POST' AS "resultType", p.post_id AS "resultId", p.title AS "title"
  FROM post p
  WHERE ((CAST(:inTitle AS boolean) AND p.title ILIKE :kw)
      OR (CAST(:inContent AS boolean) AND p.content ILIKE :kw))
    AND (p.visibility_scope = 'ALL'
      OR (p.visibility_scope = 'DEPARTMENT' AND EXISTS (
            SELECT 1 FROM employee me
            JOIN employee au ON au.department_id = me.department_id
            WHERE me.employee_id = CAST(:userId AS bigint)
              AND au.employee_id = p.author_id))
      OR (p.visibility_scope = 'INDIVIDUAL' AND p.author_id = CAST(:userId AS bigint)))
  UNION ALL
  SELECT 'APPROVAL_DOCUMENT' AS "resultType", d.approval_document_id AS "resultId", d.title AS "title"
  FROM approval_document d
  WHERE ((CAST(:inTitle AS boolean) AND d.title ILIKE :kw)
      OR (CAST(:inContent AS boolean) AND d.body ILIKE :kw))
    AND d.drafter_id = CAST(:userId AS bigint)
  UNION ALL
  SELECT 'ATTACHMENT' AS "resultType", a.attachment_id AS "resultId", a.file_name AS "title"
  FROM attachment a
  WHERE CAST(:inFile AS boolean) AND a.file_name ILIKE :kw
    AND a.uploader_id = CAST(:userId AS bigint)
`;

function intOf(raw: unknown, fallback: number): number {
  if (raw === undefined || raw === null || raw === '') {
    return fallback;
  }
  const n = Number(raw);
  if (!Number.isInteger(n)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '페이지 값이 올바르지 않습니다.');
  }
  return n;
}

@Controller('api/v1')
export class FnSfr02605Controller {
  @Get('/search')
  async searchGroupware(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    const keyword = typeof query['keyword'] === 'string' ? query['keyword'].trim() : '';
    if (!keyword) {
      throw new ApiError(422, 'KEYWORD_REQUIRED', '검색어를 입력해 주세요.');
    }
    const rawTarget = query['searchTarget'];
    const target = typeof rawTarget === 'string' ? rawTarget.trim() : '';
    if (target && !TARGETS.includes(target)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '검색 대상이 올바르지 않습니다.');
    }
    const page = intOf(query['page'], 0);
    const size = intOf(query['size'], DEFAULT_SIZE);
    if (page < 0 || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '페이지 값이 올바르지 않습니다.');
    }
    const pageSize = Math.min(size, MAX_SIZE);
    const escaped = keyword.replace(/[\\%_]/g, (c) => '\\' + c);
    const params = {
      kw: '%' + escaped + '%',
      inTitle: !target || target === '제목',
      inContent: !target || target === '내용',
      inFile: !target || target === '첨부파일 제목',
      userId: user.id,
    };
    return transaction(async (db) => {
      const totalRows = await db.query(
        `SELECT COUNT(*) AS "total" FROM (${RESULT_SQL}) r`,
        params,
      );
      const items = await db.query(
        `SELECT r."resultType", r."resultId", r."title"
         FROM (${RESULT_SQL}) r
         ORDER BY r."resultType", r."resultId" DESC
         LIMIT :limit OFFSET :offset`,
        { ...params, limit: pageSize, offset: page * pageSize },
      );
      return {
        items,
        page,
        size: pageSize,
        total: Number(totalRows[0]['total']),
      };
    });
  }
}

