import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  Drawer,
  Field,
  Filters,
  Pager,
  Pairs,
  RefName,
  Select,
  TextInput,
  Tiles,
  call,
  useData,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const TARGET_OPTIONS: [string, string][] = [
  ['제목', '제목'],
  ['내용', '내용'],
  ['첨부파일 제목', '첨부파일 제목'],
  ['첨부파일 내용', '첨부파일 내용'],
];

const TYPE_LABEL: Record<string, string> = {
  POST: '게시물',
  APPROVAL_DOCUMENT: '결재문서',
  ATTACHMENT: '첨부파일',
};

const TYPE_TABLE: Record<string, string> = {
  POST: 'post',
  APPROVAL_DOCUMENT: 'approval_document',
  ATTACHMENT: 'attachment',
};

interface Applied {
  keyword: string;
  target: string;
}

export default function FnSfr02605Page({ role, notify }: PageProps) {
  const [keyword, setKeyword] = useState('');
  const [target, setTarget] = useState('');
  const [applied, setApplied] = useState<Applied | null>(null);
  const [page, setPage] = useState(0);
  const [message, setMessage] = useState('');
  const [selected, setSelected] = useState<Row | null>(null);

  const { data, error, loading } = useData<Page | null>(async () => {
    if (!applied) {
      return null;
    }
    return call<Page>('GET', '/search', role, undefined, {
      keyword: applied.keyword,
      searchTarget: applied.target,
      page,
      size: 20,
    });
  }, [applied, page, role]);

  const search = () => {
    if (!keyword.trim()) {
      setMessage('검색어를 입력해 주세요.');
      notify('검색어를 입력해 주세요.');
      return;
    }
    setMessage('');
    setPage(0);
    setApplied({ keyword: keyword.trim(), target });
  };

  const reset = () => {
    setKeyword('');
    setTarget('');
    setMessage('');
    setPage(0);
    setApplied(null);
  };

  const rows = data ? data.items : [];
  const total = data ? data.total : 0;
  const emptyText = applied ? '일치하는 검색 결과가 없습니다.' : '검색어를 입력하고 조회하세요.';

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>통합검색 조건</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="검색어" required>
            <TextInput value={keyword} onChange={setKeyword} placeholder="검색어 입력" />
          </Field>
          <Field label="검색 대상" hint="생략 시 전체 대상으로 검색합니다.">
            <Select value={target} onChange={setTarget} options={TARGET_OPTIONS} placeholder="전체" />
          </Field>
        </Filters>
        {message ? <p>{message}</p> : null}
        {error ? <p>{error}</p> : null}
      </section>
      <section className="box span-8">
        <h2>검색 결과</h2>
        <Band total={total} />
        <DataTable
          columns={[
            {
              key: 'resultType',
              label: '결과 데이터 종류',
              render: (r) => <Badge value={TYPE_LABEL[String(r.resultType)] || String(r.resultType)} />,
            },
            { key: 'title', label: '결과 제목' },
          ]}
          rows={rows}
          onRowClick={(r) => setSelected(r)}
          empty={loading ? '불러오는 중입니다.' : emptyText}
        />
        <Pager page={page} size={20} total={total} onPage={setPage} />
      </section>
      <section className="box span-4">
        <h2>검색 현황</h2>
        <Tiles
          items={[
            ['전체 결과', total],
            ['현재 쪽 결과', rows.length],
          ]}
        />
      </section>
      {selected ? (
        <Drawer title="검색 결과 상세" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['결과 데이터 종류', TYPE_LABEL[String(selected.resultType)] || String(selected.resultType)],
              ['결과 제목', String(selected.title)],
              [
                '결과 데이터',
                TYPE_TABLE[String(selected.resultType)] ? (
                  <RefName table={TYPE_TABLE[String(selected.resultType)]} role={role} value={selected.resultId} />
                ) : (
                  ''
                ),
              ],
            ]}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
